def rr(path,sha):return dict(path=str(path),sha256=sha)
def authenticated_module(path,sha,name):
    with Path(path).open('rb') as f:
        a=os.fstat(f.fileno());raw=f.read(2*1024**2+1);z=os.fstat(f.fileno())
    if len(raw)>2*1024**2 or hashlib.sha256(raw).hexdigest()!=sha or (a.st_dev,a.st_size,a.st_mtime_ns,a.st_ctime_ns)!=(z.st_dev,z.st_size,z.st_mtime_ns,z.st_ctime_ns):raise ValueError('exact stable authenticated source buffer')
    m=types.ModuleType(name);m.__file__=str(path);exec(compile(raw,str(path),'exec'),m.__dict__);return m
def binding():return authenticated_module(BIND,BIND_SHA,'_report13_binding')
def closed_wait(b,ref,expected):
    w=b.read(ref)
    b.need(w.get('waitpid_observed') is True and type(w.get('child_pid')) is int and w['child_pid']==w.get('waited_pid'),'real wait4 PID identity')
    b.need(type(w.get('raw_wait_status')) is int and type(w.get('actual_wait_exit')) is int and w['actual_wait_exit']==expected,'typed actual exit')
    b.need(os.WIFEXITED(w['raw_wait_status']) or os.WIFSIGNALED(w['raw_wait_status']),'terminal raw wait')
    b.need(os.waitstatus_to_exitcode(w['raw_wait_status'])==expected,'raw/exit agreement')
    b.need(w['owned_identities'] and all(b.fresh_absent(i) for i in w['owned_identities']),'exact owned fresh absence')
    b.need(b.sha(w['log'])==w['log_sha256'],'actual log SHA')
    return w
